CREATE TABLE bus_search(id UUID PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,mode VARCHAR(10) NOT NULL DEFAULT 'MOCK' CHECK(mode='MOCK'),payload JSONB NOT NULL,CHECK(expires_at>created_at),CHECK((payload->>'id')::uuid=id AND payload->>'mode'='MOCK'));
CREATE INDEX bus_search_expiry ON bus_search(expires_at);
CREATE TABLE cab_search(id UUID PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,mode VARCHAR(10) NOT NULL DEFAULT 'MOCK' CHECK(mode='MOCK'),payload JSONB NOT NULL,CHECK(expires_at>created_at),CHECK((payload->>'id')::uuid=id AND payload->>'mode'='MOCK'));
CREATE INDEX cab_search_expiry ON cab_search(expires_at);
CREATE TABLE holiday_quote(id UUID PRIMARY KEY,customer_id UUID NOT NULL REFERENCES customer_account(id),created_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL,CHECK(expires_at>created_at),CHECK((payload->>'id')::uuid=id AND (payload->>'owner')::uuid=customer_id AND payload->>'mode'='MOCK' AND (payload->>'version')::int=1));
ALTER TABLE holiday_quote ADD CONSTRAINT holiday_quote_owner_unique UNIQUE(id,customer_id);
CREATE INDEX holiday_quote_owner ON holiday_quote(customer_id,created_at DESC);
CREATE TABLE holiday_enquiry(id UUID PRIMARY KEY,quote_id UUID NOT NULL UNIQUE REFERENCES holiday_quote(id),customer_id UUID NOT NULL REFERENCES customer_account(id),payload JSONB NOT NULL,CHECK((payload->>'id')::uuid=id AND (payload->>'owner')::uuid=customer_id AND (payload->'quote'->>'id')::uuid=quote_id AND payload->>'status'='RECORDED_LOCALLY' AND payload->>'mode'='MOCK'));
ALTER TABLE holiday_enquiry ADD CONSTRAINT holiday_enquiry_owned_quote FOREIGN KEY(quote_id,customer_id) REFERENCES holiday_quote(id,customer_id);
ALTER TABLE holiday_enquiry ADD CONSTRAINT holiday_enquiry_quote_owner CHECK((payload->'quote'->>'owner')::uuid=customer_id);
CREATE INDEX holiday_enquiry_owner ON holiday_enquiry(customer_id,id);
CREATE TABLE holiday_command(customer_id UUID NOT NULL REFERENCES customer_account(id),operation VARCHAR(12) NOT NULL CHECK(operation IN('QUOTE','ENQUIRY')),command_key VARCHAR(100) NOT NULL,fingerprint VARCHAR(64) NOT NULL,resource_id UUID NOT NULL,PRIMARY KEY(customer_id,operation,command_key));
CREATE TABLE holiday_outbox(id UUID PRIMARY KEY,aggregate_id UUID NOT NULL UNIQUE,envelope JSONB NOT NULL,CHECK((envelope->>'eventId')::uuid=id AND (envelope->>'aggregateId')::uuid=aggregate_id AND envelope->>'mode'='MOCK' AND envelope->>'producer'='holidays'),CHECK(NOT envelope ?| ARRAY['contactName','email','notes','owner']));
CREATE TRIGGER immutable_bus_search BEFORE UPDATE ON bus_search FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TRIGGER immutable_cab_search BEFORE UPDATE ON cab_search FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TRIGGER immutable_holiday_quote BEFORE UPDATE OR DELETE ON holiday_quote FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TRIGGER immutable_holiday_enquiry BEFORE UPDATE OR DELETE ON holiday_enquiry FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TRIGGER immutable_holiday_command BEFORE UPDATE OR DELETE ON holiday_command FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
CREATE TRIGGER immutable_holiday_outbox BEFORE UPDATE OR DELETE ON holiday_outbox FOR EACH ROW EXECUTE FUNCTION reject_booking_command_change();
